-- ============================================
-- LUMA — Thème 16 : LONG 1/3 x4 — Un mois de travail saisonnier complet dans une ferm
-- ============================================


update scenarios set content = '{"characters": {"farmer": "le fermier", "coworker": "un collègue", "coworker2": "un nouveau collègue"}, "start_node": "n1", "nodes": {"n1": {"speaker": "farmer", "text": "First day! We start early here — 5:30am sharp. Ready for that?", "text_fr": "Premier jour ! On commence tôt ici — 5h30 pile. Prêt pour ça ?", "choices": [{"text": "Absolutely, I''m ready to dive right in.", "text_fr": "Absolument, je suis prêt à plonger dedans.", "next": "n2"}, {"text": "Honestly, that''s earlier than I''m used to, but I''ll adapt.", "text_fr": "Honnêtement, c''est plus tôt que ce à quoi je suis habitué, mais je vais m''adapter.", "next": "n2b"}]}, "n2": {"speaker": "coworker", "text": "Welcome aboard! First week is always the toughest, your body needs to adjust.", "text_fr": "Bienvenue à bord ! La première semaine est toujours la plus dure, ton corps doit s''adapter.", "choices": [{"text": "Any tips for surviving that adjustment period?", "text_fr": "Des conseils pour survivre à cette période d''adaptation ?", "next": "n3"}]}, "n2b": {"speaker": "coworker", "text": "You''ll get used to it fast, trust me. The sunrise out here makes it worth it.", "text_fr": "Tu vas t''y habituer vite, crois-moi. Le lever du soleil ici en vaut la peine.", "choices": [{"text": "I''ll try to appreciate that perspective during the early mornings.", "text_fr": "Je vais essayer d''apprécier cette perspective pendant les matins tôt.", "next": "n3"}]}, "n3": {"speaker": "coworker", "text": "Stay hydrated, wear sunscreen religiously, and don''t compare your pace to others at first.", "text_fr": "Reste hydraté, mets de la crème solaire religieusement, et compare pas ton rythme aux autres au début.", "choices": [{"text": "Good advice, I''ll keep that in mind these first few days.", "text_fr": "Bon conseil, je vais garder ça en tête ces premiers jours.", "next": "n4"}]}, "n4": {"speaker": "you_thought", "text": "(By day three, your body aches everywhere, but you''re finding a rhythm.)", "text_fr": "(Au jour trois, votre corps vous fait mal partout, mais vous trouvez un rythme.)", "choices": [{"text": "(Push through, focusing on small improvements each day.)", "text_fr": "(Continue, en te concentrant sur de petites améliorations chaque jour.)", "next": "n5"}]}, "n5": {"speaker": "farmer", "text": "(One week in) You''re picking up speed nicely. How are you holding up?", "text_fr": "(Une semaine plus tard) Vous prenez de la vitesse joliment. Comment vous tenez le coup ?", "choices": [{"text": "Honestly, better than I expected. My body''s adjusting.", "text_fr": "Honnêtement, mieux que prévu. Mon corps s''adapte.", "next": "n6"}, {"text": "Some days are harder than others, but I''m managing.", "text_fr": "Certains jours sont plus durs que d''autres, mais je gère.", "next": "n6"}]}, "n6": {"speaker": "coworker2", "text": "(New coworker arrives, clearly nervous) Is it always this intense?", "text_fr": "(Un nouveau collègue arrive, clairement nerveux) C''est toujours aussi intense ?", "choices": [{"text": "It gets easier, I promise. The first week is the hardest part.", "text_fr": "Ça devient plus facile, promis. La première semaine est la partie la plus dure.", "next": "n7"}, {"text": "Honestly, yes, but the community here makes it worth it.", "text_fr": "Honnêtement, oui, mais la communauté ici en vaut la peine.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(Two weeks in, you''ve built genuine friendships among the seasonal workers.)", "text_fr": "(Deux semaines plus tard, vous avez créé de vraies amitiés parmi les travailleurs saisonniers.)", "choices": [{"text": "(Reflect on how the community has made this experience special.)", "text_fr": "(Réfléchis à comment la communauté a rendu cette expérience spéciale.)", "next": "n8"}]}, "n8": {"speaker": "farmer", "text": "(Mid-month check-in) Your work ethic''s been noticed. We''d like to offer you a supervisor role for the rest of the season.", "text_fr": "(Point à mi-mois) Votre éthique de travail a été remarquée. On aimerait vous offrir un rôle de superviseur pour le reste de la saison.", "choices": [{"text": "I''m honored, thank you! I''d love to take on that responsibility.", "text_fr": "Je suis honoré, merci ! J''aimerais prendre cette responsabilité.", "next": "n9"}, {"text": "That''s really flattering, though I want to make sure I can handle it well.", "text_fr": "C''est vraiment flatteur, même si je veux m''assurer de pouvoir bien la gérer.", "next": "n9"}]}, "n9": {"speaker": "farmer", "text": "You''ll do great. It comes with a pay bump too, well deserved.", "text_fr": "Vous allez très bien vous en sortir. Ça vient aussi avec une augmentation de salaire, bien méritée.", "choices": [{"text": "Thank you for trusting me with this, I won''t let you down.", "text_fr": "Merci de me faire confiance avec ça, je vais pas vous décevoir.", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(As supervisor, you help train new arrivals, remembering your own tough first days.)", "text_fr": "(En tant que superviseur, vous aidez à former les nouveaux arrivants, en vous souvenant de vos propres premiers jours difficiles.)", "choices": [{"text": "(Share your own early struggles to reassure a nervous new worker.)", "text_fr": "(Partage tes propres difficultés du début pour rassurer un nouveau travailleur nerveux.)", "next": "n11"}]}, "n11": {"speaker": "coworker2", "text": "Thanks for that, it really helps hearing you struggled too at first.", "text_fr": "Merci pour ça, ça aide vraiment d''entendre que tu as aussi eu du mal au début.", "choices": [{"text": "We all start somewhere. You''re doing great already.", "text_fr": "On commence tous quelque part. Tu te débrouilles déjà très bien.", "next": "n12"}]}, "n12": {"speaker": "farmer", "text": "(Final week) A month already! How does it feel looking back?", "text_fr": "(Dernière semaine) Déjà un mois ! Ça fait quoi de regarder en arrière ?", "choices": [{"text": "Honestly, transformative. I came in a stranger and I''m leaving with real friends.", "text_fr": "Honnêtement, transformateur. Je suis arrivé étranger et je pars avec de vrais amis.", "next": "n13"}]}, "n13": {"speaker": "farmer", "text": "That''s exactly what this work does to people, if they let it. You should be proud.", "text_fr": "C''est exactement ce que ce travail fait aux gens, s''ils le laissent faire. Vous devriez être fier.", "choices": [{"text": "I really am. Thank you for the opportunity and the trust.", "text_fr": "Je le suis vraiment. Merci pour l''opportunité et la confiance.", "next": "end_month"}]}, "end_month": {"speaker": "coworker", "text": "You''ve earned every bit of this experience. Safe travels on the rest of your journey!", "text_fr": "Tu as mérité chaque instant de cette expérience. Bon voyage pour le reste de ton périple !", "end": true, "ending_label": "Un mois de travail saisonnier transformateur 🍇🌅🤝"}}}'::jsonb, is_playable = true
where title = 'Un mois de travail saisonnier complet dans une ferme'
  and theme_id = (select id from scenario_themes where position = 16 and language_id = (select id from languages where code = 'en'));
